<fieldset class="m3-card m3-card--outlined" data-pathway-row="route" style="min-width:0;padding:16px;margin-block:12px"><legend>{{ __('Route into this career') }}</legend>
<x-page.field :id="'pathway-route-'.$index.'-type'" :name="'career_routes['.$index.'][type]'" type="select" :label="__('Route type')" :value="$row['type']" :options="['university'=>__('University'),'tvet'=>__('TVET college'),'learnership'=>__('Learnership')]" :required="true" :restore-old-input="false" />
<x-page.field :id="'pathway-route-'.$index.'-title'" :name="'career_routes['.$index.'][title]'" :label="__('Qualification or programme')" :value="$row['title']" :required="true" maxlength="191" :restore-old-input="false" />
<x-page.field :id="'pathway-route-'.$index.'-provider'" :name="'career_routes['.$index.'][provider]'" :label="__('Institution, college, SETA or employer')" :value="$row['provider']" :required="true" maxlength="191" :restore-old-input="false" />
<x-page.field :id="'pathway-route-'.$index.'-note'" :name="'career_routes['.$index.'][entry_note]'" type="textarea" :label="__('Entry requirements as the source states them')" :value="$row['entry_note']" :required="true" maxlength="1000" :restore-old-input="false" />
<x-page.field :id="'pathway-route-'.$index.'-source-title'" :name="'career_routes['.$index.'][source_title]'" :label="__('Source document title')" :value="$row['source_title']" :required="true" maxlength="240" :restore-old-input="false" />
<x-page.field :id="'pathway-route-'.$index.'-source-url'" :name="'career_routes['.$index.'][source_url]'" type="url" :label="__('Public HTTPS source address')" :value="$row['source_url']" :required="true" maxlength="2048" :restore-old-input="false" />
<x-page.field :id="'pathway-route-'.$index.'-programme'" :name="'career_routes['.$index.'][programme_id]'" type="select" :label="__('Linked programme source (university routes only)')" :value="$row['programme_id']" :options="$programmes" :placeholder="__('No linked programme')" :restore-old-input="false" />
<button type="button" class="m3-button m3-button--text" disabled data-pathway-remove>{{ __('Remove route') }}</button></fieldset>
